// =========================================================
// KYDNO KORE - 5 REEL 3D COIN ANIMATION
// Clean circular coin version
// =========================================================

const KYDNO_COIN_ASSETS = {
    heads: "assets/kydno_kore_heads_coin.png",
        tails: "assets/kydno_kore_tails_coin.png"
        };

        const KYDNO_REEL_SIDES = [
            "heads",
                "tails",
                    "heads",
                        "tails",
                            "heads",
                                "tails",
                                    "heads",
                                        "tails"
                                        ];         
     // =========================================================
     // KYDNO KORE - VERTICAL COIN REEL
     // =========================================================
     
     function createKydnoCoin(side) {
     
         const coin = document.createElement("img");
         
             coin.className = "kydno-reel-coin";
             
                 coin.src = KYDNO_COIN_ASSETS[side];
                 
                     coin.alt =
                             side === "heads"
                                         ? "Kydno Kore Heads Coin"
                                                     : "Kydno Kore Tails Coin";
                                                     
                                                         coin.dataset.side = side;
                                                         
                                                             return coin;
                                                             }
                                                             
                                                             
                                                                                                                     
                                                             // =========================================================
                                                             // CREATE ONE VERTICAL REEL
                                                             // =========================================================

                                                             function createKydnoVerticalReel(reelElement) {

                                                                 if (!reelElement) return;

                                                                     reelElement.innerHTML = "";

                                                                         const track =
                                                                                 document.createElement("div");

                                                                                     track.className =
                                                                                             "kydno-vertical-track";


                                                                                                 // Lots of coins so the reel can continuously
                                                                                                     // travel downward without running out.

                                                                                                         for (let i = 0; i < 32; i++) {

                                                                                                                 const side =
                                                                                                                             KYDNO_REEL_SIDES[
                                                                                                                                             i % KYDNO_REEL_SIDES.length
                                                                                                                                                         ];

                                                                                                                                                                 const coin =
                                                                                                                                                                             createKydnoCoin(side);

                                                                                                                                                                                     track.appendChild(coin);
                                                                                                                                                                                         }


                                                                                                                                                                                             reelElement.appendChild(track);


                                                                                                                                                                                                 // Large final result coin.

                                                                                                                                                                                                     const landedCoin =
                                                                                                                                                                                                             document.createElement("img");

                                                                                                                                                                                                                 landedCoin.className =
                                                                                                                                                                                                                         "kydno-landed-coin";

                                                                                                                                                                                                                             landedCoin.alt = "";

                                                                                                                                                                                                                                 reelElement.appendChild(
                                                                                                                                                                                                                                         landedCoin
                                                                                                                                                                                                                                             );
                                                                                                                                                                                                                                             }
                                                                                                                                                                                                     
                                                                                                                                                                                                     
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     // BUILD ALL FIVE REELS
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     
                                                                                                                                                                                                     const kydnoReelTracks = [];
                                                                                                                                                                                                     
                                                                                                                                                                                                     for (let i = 1; i <= 5; i++) {
                                                                                                                                                                                                     
                                                                                                                                                                                                         const reelElement =
                                                                                                                                                                                                                 document.getElementById(
                                                                                                                                                                                                                             `kydno-reel-${i}`
                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                         createKydnoVerticalReel(
                                                                                                                                                                                                                                                 reelElement
                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                         const track =
                                                                                                                                                                                                                                                                 reelElement?.querySelector(
                                                                                                                                                                                                                                                                             ".kydno-vertical-track"
                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                         if (track) {
                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                 kydnoReelTracks.push(
                                                                                                                                                                                                                                                                                                             track
                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         // SHOW LANDED COIN
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         function showKydnoLandedCoin(
                                                                                                                                                                                                                                                                                                                             reelElement,
                                                                                                                                                                                                                                                                                                                                 side
                                                                                                                                                                                                                                                                                                                                 ) {
                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                     if (!reelElement) return;
                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                         const landedCoin =
                                                                                                                                                                                                                                                                                                                                                 reelElement.querySelector(
                                                                                                                                                                                                                                                                                                                                                             ".kydno-landed-coin"
                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                         if (!landedCoin) return;
                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                             landedCoin.src =
                                                                                                                                                                                                                                                                                                                                                                                     KYDNO_COIN_ASSETS[side];
                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                         landedCoin.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                 "show"
                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                     }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
    // =========================================================
    // KYDNO KORE - 5 REEL SPIN TEST
    // =========================================================

    const KYDNO_TEST_RESULTS = [
        "heads",
            "tails",
                "heads",
                    "tails",
                        "heads"
                        ];

       // =========================================================
       // VERTICAL FALLING REEL SPIN
       // =========================================================

       // =========================================================
       // VERTICAL REEL SPIN
       // =========================================================

       // =========================================================
       // CONTINUOUS DOWNWARD REEL SPIN
       // =========================================================

// =========================================================
// CONTINUOUS REEL SPIN + INDIVIDUAL LANDING
// =========================================================

function spinKydnoReel(
    track,
        reelElement,
            resultSide,
                reelNumber,
                    duration
                    ) {

                        if (!track || !reelElement) return;

                            const coins =
                                    Array.from(
                                                track.querySelectorAll(".kydno-reel-coin")
                                                        );

                                                            if (coins.length < 8) return;

                                                                const coinHeight =
                                                                        coins[0].getBoundingClientRect().height;

                                                                            const firstCoin =
                                                                                    coins[0];

                                                                                        const secondCoin =
                                                                                                coins[1];

                                                                                                    const step =
                                                                                                            secondCoin.offsetTop -
                                                                                                                    firstCoin.offsetTop;

                                                                                                                        if (!step) return;

                                                                                                                            const reelHeight =
                                                                                                                                    reelElement.clientHeight;

                                                                                                                                        /*
                                                                                                                                                Start with a coin around the center.
                                                                                                                                                    */

                                                                                                                                                        let currentY =
                                                                                                                                                                (reelHeight / 2) -
                                                                                                                                                                        (2 * step) -
                                                                                                                                                                                (coinHeight / 2);

                                                                                                                                                                                    track.style.transition = "none";

                                                                                                                                                                                        track.style.transform =
                                                                                                                                                                                                `translate(-50%, ${currentY}px)`;

                                                                                                                                                                                                    /*
                                                                                                                                                                                                            Each reel gets its own continuous speed.

                                                                                                                                                                                                                    Reel 5 starts faster so its final
                                                                                                                                                                                                                            slowdown feels more dramatic.
                                                                                                                                                                                                                                */

                                                                                                                                                                                                                                    const speed =
                                                                                                                                                                                                                                            reelNumber === 5
                                                                                                                                                                                                                                                        ? 1.55
                                                                                                                                                                                                                                                                    : 1.25;

                                                                                                                                                                                                                                                                        let running = true;

                                                                                                                                                                                                                                                                            const startTime =
                                                                                                                                                                                                                                                                                    performance.now();

                                                                                                                                                                                                                                                                                        /*
                                                                                                                                                                                                                                                                                                Continuously move the reel downward.
                                                                                                                                                                                                                                                                                                    */

                                                                                                                                                                                                                                                                                                        function continuousSpin(currentTime) {

                                                                                                                                                                                                                                                                                                                if (!running) return;

                                                                                                                                                                                                                                                                                                                        currentY += speed;

                                                                                                                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                                                                                                                            Recycle the first coin to the bottom
                                                                                                                                                                                                                                                                                                                                                        whenever it has moved through the window.

                                                                                                                                                                                                                                                                                                                                                                    This allows the reel to spin continuously
                                                                                                                                                                                                                                                                                                                                                                                without ever running out of coins.
                                                                                                                                                                                                                                                                                                                                                                                        */

                                                                                                                                                                                                                                                                                                                                                                                                if (currentY > step) {

                                                                                                                                                                                                                                                                                                                                                                                                            currentY -= step;

                                                                                                                                                                                                                                                                                                                                                                                                                        const first =
                                                                                                                                                                                                                                                                                                                                                                                                                                        track.firstElementChild;

                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (first) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    track.appendChild(first);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                track.style.transform =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `translate(-50%, ${currentY}px)`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Only THIS reel checks its own timer.

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            The other reels continue independently.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const elapsed =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currentTime - startTime;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (elapsed >= duration) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            running = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        landKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resultSide,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelNumber
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            continuousSpin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    continuousSpin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // INDIVIDUAL REEL LANDING
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =========================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function landKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    resultSide,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelNumber
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!track || !reelElement) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const coins =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Array.from(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    track.querySelectorAll(".kydno-reel-coin")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!coins.length) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Hide the moving coins once this reel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    reaches its landing sequence.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            coins.forEach((coin) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    coin.style.opacity = "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Find the large result coin.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const landedCoin =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    reelElement.querySelector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ".kydno-landed-coin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!landedCoin) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                landedCoin.src =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        KYDNO_COIN_ASSETS[resultSide];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            landedCoin.classList.remove("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Force the browser to restart the
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                landing animation.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        void landedCoin.offsetWidth;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Normal reels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            jiggle → enlarge → settle.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (reelNumber !== 5) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            landedCoin.classList.add("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            REEL 5 — DRAMATIC FINAL PULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Reel 5 first pulls backward,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    briefly holds,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            then snaps into its final coin.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    reelElement.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "kydno-reel-five-pull"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            landedCoin.classList.add("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, 260);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            reelElement.classList.remove(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "kydno-reel-five-pull"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }, 950);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                 
                                                                
  // =========================================================
  // RUN THE 5 REEL SPIN TEST
  // =========================================================

  function runKydnoSpinTest() {

      // Reset the reels first
         kydnoReelTracks.forEach((track) => {

                track.style.transition = "none";

                    track.style.transform =
                            "translate(-50%, 0px)";

                                track
                                        .querySelectorAll(".kydno-reel-coin")
                                                .forEach((coin) => {
                                                            coin.style.opacity = "1";
                                                                    });
                                                                    });
         

                                                                              // Hide previous result coins
                                                                                  kydnoReelTracks.forEach((track, index) => {

                                                                                          const reelElement =
                                                                                                      document.getElementById(
                                                                                                                      `kydno-reel-${index + 1}`
                                                                                                                                  );

                                                                                                                                          const landedCoin =
                                                                                                                                                      reelElement?.querySelector(
                                                                                                                                                                      ".kydno-landed-coin"
                                                                                                                                                                                  );

                                                                                                                                                                                          if (landedCoin) {
                                                                                                                                                                                                      landedCoin.classList.remove("show");
                                                                                                                                                                                                                  landedCoin.removeAttribute("src");
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                  // Wait for the reset to happen
                                                                                                                                                                                                                                      requestAnimationFrame(() => {

                                                                                                                                                                                                                                              requestAnimationFrame(() => {

                                                                                                                                                                                                                                                          // Reel 1 → 2 → 3 → 4
                                                                                                                                                                                                                                                                      // Reel 5 gets the dramatic slowdown

                                                                                                                                                                                                                                                                                  const durations = [
                                                                                                                                                                                                                                                                                        1300,
                                                                                                                                                                                                                                                                                            1700,
                                                                                                                                                                                                                                                                                                2100,
                                                                                                                                                                                                                                                                                                    2500,
                                                                                                                                                                                                                                                                                                        4000
                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                                                                                                                                                          kydnoReelTracks.forEach(
                                                                                                                                                                                                                                                                                                                                                                                                          (track, index) => {

                                                                                                                                                                                                                                                                                                                                                                                                                              const reelNumber =
                                                                                                                                                                                                                                                                                                                                                                                                                                                      index + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const reelElement =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `kydno-reel-${reelNumber}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          spinKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  KYDNO_TEST_RESULTS[index],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelNumber,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  durations[index]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Automatically start the test
